<?php
namespace App\Http\Controllers;
use App\Models\User;use App\Services\Auth\OtpService;use Illuminate\Http\Request;use Illuminate\Support\Facades\Auth;use Illuminate\Support\Facades\Hash;use Illuminate\Validation\ValidationException;
class EmailPhoneController extends Controller
{
 public function send(Request $request,OtpService $otp){abort_unless(session('email_onboarding.verified')&&session('email_onboarding.email'),403);$data=$request->validate(['phone'=>['required','regex:/^09\d{9}$/']]);$phone=$data['phone'];if(User::where('phone',$phone)->exists())return back()->withErrors(['phone'=>'این شماره قبلاً دارای حساب است. برای ورود از صفحه ورود استفاده کنید.'])->withInput();try{$otp->send($phone);}catch(\Throwable $e){return back()->withErrors(['phone'=>$e->getMessage()])->withInput();}$request->session()->put(['otp.phone'=>$phone,'otp.purpose'=>'email_onboarding']);return redirect()->route('otp.show')->with('success','کد تأیید شماره موبایل ارسال شد.');}
 public function verify(Request $request,OtpService $otp){abort_unless(session('email_onboarding.verified')&&session('email_onboarding.email'),403);$data=$request->validate(['phone'=>['required','regex:/^09\d{9}$/'],'code'=>['required','digits:6']]);if(!$otp->verify($data['phone'],$data['code']))throw ValidationException::withMessages(['code'=>'کد تأیید نادرست یا منقضی شده است.']);$email=session('email_onboarding.email');$user=User::firstOrCreate(['phone'=>$data['phone']],['first_name'=>'','last_name'=>'','email'=>$email,'password'=>Hash::make(bin2hex(random_bytes(16))),'role'=>'buyer','is_active'=>true,'phone_verified_at'=>now()]);if($user->email!==$email){$user->update(['email'=>$email]);}$request->session()->forget(['email_onboarding.verified','email_onboarding.email','otp.phone','otp.purpose','otp.verified']);Auth::login($user);$request->session()->regenerate();return redirect()->route('account.profile')->with('success','حساب شما با شماره موبایل فعال شد. لطفاً اطلاعات پروفایل را تکمیل کنید.');}
}